using System.Collections.Generic;
using System.Collections.Immutable;

namespace Cosmos.EffectAlgebra;

/// <summary>
/// §3.2.3 — Compatible：16 对全函数 + 对称。无未覆盖对（P2）。
/// CONFLICT = {(Create,Create),(Move,Move),(Release,Release)}。
/// Unknown 按 Use 处理（fail-closed 最弱兼容，P4）。
/// </summary>
public static class Compatible
{
    // §3.2.3 P4：Unknown 解析为 Use（最弱兼容，保守）
    private static Mode Resolve(Mode m) => m == Mode.Unknown ? Mode.Use : m;

    /// <summary>§3.2.3 全函数定义；(P1) 对称：IsCompatible(a,b)=IsCompatible(b,a)。</summary>
    public static bool IsCompatible(Mode a, Mode b)
    {
        var aa = Resolve(a);
        var bb = Resolve(b);
        if (aa == Mode.Use || bb == Mode.Use) return true;   // use 最弱共享权限，与任意 mode 兼容
        // §3.2.3 良性生命周期配对（P3：create+release 不再误判冲突）
        if ((aa, bb) is (Mode.Create, Mode.Release) or (Mode.Release, Mode.Create)) return true;
        if ((aa, bb) is (Mode.Create, Mode.Move) or (Mode.Move, Mode.Create)) return true;
        if ((aa, bb) is (Mode.Release, Mode.Move) or (Mode.Move, Mode.Release)) return true;
        return false; // CONFLICT 集：create+create / move+move / release+release
    }
}

/// <summary>
/// §3.3.2b — weight: Kind × Kind → ℝ ∪ {⊥}。⊥ 表示跨 kind 无定义 ⇒ 聚合须报错 KIND_MIX（L3）。
/// 类型表达为 partial 函数：同 kind ⇒ 1.0；跨 kind ⇒ double.NaN（约定为 ⊥ 编码，注释契约）。
/// </summary>
public static class Weight
{
    /// <summary>返回 NaN 表示 ⊥（跨 kind 未定义，触发 KIND_MIX）。</summary>
    public static double Of(Kind a, Kind b) => a == b ? 1.0 : double.NaN;
}

/// <summary>
/// §3.3.1 — net(S, scope)：按资源分组，带符号 size 求和（create/release 抵消）。
/// 仅含 occupy 桶（c.kind == Occupy）的 Claim（read/write 不进 net 守恒，§3.3.1 量纲隔离）；且仅含 ⊆* 过滤的 Claim。
/// size 用 Interval.Merge（§3.1.5b）；同资源 create(+) / release(−) 符号相反，净为 0 即守恒（DO-9 不报警）。
/// </summary>
public sealed class NetTable
{
    private readonly Dictionary<ResourceId, Interval> _net = new();

    private NetTable() { }

    /// <summary>§3.3.1 — 仅含 c.kind == Occupy 且 c.Scope ⊆* scope 的 Claim；按归一化资源分组，create/move 加 release 减。</summary>
    public static NetTable Compute(Signature sig, ScopeId scope)
    {
        var t = new NetTable();
        foreach (var c in sig.AllClaims())
        {
            if (c.Kind != Kind.Occupy) continue;      // §3.3.1 net 仅含 occupy 桶（量纲隔离）
            if (!c.Scope.IncludedIn(scope)) continue;  // §3.1.3b ⊆* 过滤
            var r = ResourceId.Normalize(c.Resource);
            var signed = c.Mode == Mode.Release ? NegateCore(c.Size) : c.Size;
            t._net.TryGetValue(r, out var cur);
            t._net[r] = cur == default ? signed : cur.Merge(signed);
        }
        return t;
    }

    // §3.3.1 带符号 size：release 取 size 的「负向」[−hi,−lo]。
    // 若任一端为 ⊤（未知上界），整体标记为 [⊤,⊤]（net 未知 ⇒ IsConserved 返回 false，交人工确认）。
    private static Interval NegateCore(Interval s)
    {
        if (s.Lo.IsTop || s.Hi.IsTop) return new Interval(NatStar.Top, NatStar.Top);
        return new Interval(NatStar.Of(s.Hi.Value), NatStar.Of(s.Lo.Value)); // [−hi, −lo]
    }

    /// <summary>资源净效应；不含该资源 ⇒ Default（净占用 1，保守）。</summary>
    public Interval this[ResourceId r] => _net.TryGetValue(ResourceId.Normalize(r), out var v) ? v : Interval.Default;

    /// <summary>§3.3.1 守恒判定：net 区间跨 0（lo≤0≤hi）⇒ 该资源生命周期闭合（DO-9 不报警）。
    /// ⊤（未知上界）视为「需人工界定」⇒ 不守恒（fail-closed，触发 DO-9 报警而非静默漏报，§3.3.1 DO-9）。</summary>
    public bool IsConserved(ResourceId r)
    {
        var v = this[r];
        // §3.3.1 DO-9 fail-closed：若 lo 或 hi 为 ⊤（未知），不宣称守恒，交由人工确认。
        if (v.Lo.IsTop || v.Hi.IsTop) return false;
        var loLeZero = v.Lo.Value == 0;
        var hiGeZero = v.Hi.Value == 0;
        return loLeZero && hiGeZero; // 缺省 Default=[1,1] ⇒ 不守恒 ⇒ 触发 DO-9 泄漏报警
    }
}

/// <summary>
/// §3.3.2 / §3.2.5 — Peak：size 求和（§3.2.5 旧 cardinality 形式已废弃，以本节为准）。
/// ω=⊤ ⇒ 返回 ⊤（上界标记，不发散，MA-002）。
/// </summary>
public static class Peak
{
    /// <summary>§3.3.2 — 对某 scope 下全部 claim 的 size 求和；任一 ⊤ ⇒ 整体 ⊤。</summary>
